    if (want) try { history.replaceState(history.state, '', location.pathname + location.hash); } catch (_) {}
    /* size order comes from EasyOrders itself (owner, 2026-11-12): nothing is reordered here */
    /* stock straight from the store, not from a possibly stale cached copy of the page data */
