      var cta = document.createElement('a'); cta.className = 'sz-cta'; cta.href = PAGE + '#' + g.id;
      cta.innerHTML = '<span class="h">رقم <b>42</b> ليس واحدًا في كل الأحذية.</span><span class="s">' + esc(TX.ctaText) + '</span><span class="b">' + esc(TX.ctaButton) + '</span>';
